"""Calculates a fibonacci of a given number"""

def fibonacci(number):
    """returns fibonacci with memoization"""
    memo = {0: 0, 1: 1}
    if not number in memo:
        memo[number] = fibonacci(number-1) + fibonacci(number-2)
    return memo[number]

